package middleware

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/assert"
)

// stubPremiumChecker is a minimal local test double for PremiumChecker — not
// a repository, so it is written by hand rather than generated by mockery.
type stubPremiumChecker struct {
	premium bool
	err     error
}

func (s stubPremiumChecker) IsPremium(context.Context, string) (bool, error) {
	return s.premium, s.err
}

func TestRequirePremium(t *testing.T) {
	gin.SetMode(gin.TestMode)
	tests := []struct {
		name       string
		checker    stubPremiumChecker
		wantStatus int
		wantNext   bool
	}{
		{name: "active subscription passes", checker: stubPremiumChecker{premium: true}, wantStatus: http.StatusOK, wantNext: true},
		{name: "no subscription blocked", checker: stubPremiumChecker{premium: false}, wantStatus: http.StatusForbidden, wantNext: false},
		{name: "checker error fails closed", checker: stubPremiumChecker{err: assert.AnError}, wantStatus: http.StatusInternalServerError, wantNext: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			r := gin.New()
			next := false
			r.GET("/premium",
				func(c *gin.Context) { c.Set(userIDKey, "user-1"); c.Next() },
				RequirePremium(tt.checker),
				func(c *gin.Context) {
					next = true
					c.Status(http.StatusOK)
				},
			)
			req := httptest.NewRequest(http.MethodGet, "/premium", nil)
			rec := httptest.NewRecorder()
			r.ServeHTTP(rec, req)
			assert.Equal(t, tt.wantStatus, rec.Code)
			assert.Equal(t, tt.wantNext, next)
		})
	}
}
